class Node:
    def __init__(self, value, next=None):
        self.value = value
        self.next = next

def reverse(head):
    prev = None
    current = head
    while current:
        following = current.next
        current.next = prev
        prev = current
        current = following
    return prev

def solve(values):
    head = None
    for value in reversed(values):
        head = Node(value, head)
    node = reverse(head)
    result = []
    while node:
        result.append(node.value)
        node = node.next
    return result

