from collections import Counter

def solve(s, t):
    if not t:
        return ""
    need = Counter(t)
    counts = {}
    have = left = 0
    best_start, best_length = 0, float("inf")
    for right, ch in enumerate(s):
        counts[ch] = counts.get(ch, 0) + 1
        if ch in need and counts[ch] == need[ch]:
            have += 1
        while have == len(need):
            if right - left + 1 < best_length:
                best_start, best_length = left, right - left + 1
            removed = s[left]
            counts[removed] -= 1
            if removed in need and counts[removed] < need[removed]:
                have -= 1
            left += 1
    return "" if best_length == float("inf") else s[best_start:best_start + best_length]

