def encode(words):
    return ''.join(str(len(word)) + '#' + word for word in words)
def decode(data):
    words, i = [], 0
    while i < len(data):
        stop = data.index('#', i)
        length = int(data[i:stop])
        i = stop + 1
        words.append(data[i:i+length])
        i += length
    return words
def solve(words):
    return decode(encode(words))

