    pal = [[False]*n for _ in range(n)]
    for i in range(n-1,-1,-1):
        for j in range(i,n):
            pal[i][j] = s[i] == s[j] and (j-i < 2 or pal[i+1][j-1])
    out, path = [], []
    def visit(start):
        if start == n:
            out.append(path.copy()); return
