    cols, diag, anti = set(), set(), set()
    def visit(row):
        if row == n:
            out.append(['.'*c+'Q'+'.'*(n-c-1) for c in positions]); return
        for c in range(n):
            if c in cols or row-c in diag or row+c in anti: continue
            cols.add(c); diag.add(row-c); anti.add(row+c); positions.append(c)
