class Node:
    def __init__(self, value=0, nxt=None):
        self.val, self.next = value, nxt

def build(values):
    dummy = tail = Node()
    for value in values:
        tail.next = Node(value)
        tail = tail.next
    return dummy.next

def values(head):
    result = []
    while head:
        result.append(head.val)
        head = head.next
    return result

def solve(a,b):
    a,b = build(a),build(b)
    dummy = tail = Node()
    while a and b:
        if a.val <= b.val:
            tail.next,a = a,a.next
        else:
            tail.next,b = b,b.next
        tail = tail.next
    tail.next = a or b
    return values(dummy.next)

reorder-list.code:
class Node:
    def __init__(self, value=0, nxt=None):
        self.val, self.next = value, nxt

def build(values):
    dummy = tail = Node()
    for value in values:
        tail.next = Node(value)
        tail = tail.next
    return dummy.next

def values(head):
    result = []
    while head:
        result.append(head.val)
        head = head.next
    return result

def solve(items):
    head = build(items)
    if not head or not head.next: return items[:]
    slow,fast = head,head.next
    while fast and fast.next:
        slow,fast = slow.next,fast.next.next
    second,slow.next = slow.next,None
    prev = None
    while second:
        nxt = second.next
        second.next,prev,second = prev,second,nxt
    first,second = head,prev
    while second:
        a,b = first.next,second.next
        first.next,second.next = second,a
        first,second = a,b
    return values(head)

