    slow.next = slow.next.next
    return values(dummy.next)

copy-list-with-random-pointer.code:
class Node:
    def __init__(self,value):
        self.val,self.next,self.random = value,None,None

def solve(items):
    nodes = [Node(value) for value,_ in items]
    for i,(_,random) in enumerate(items):
        nodes[i].next = nodes[i+1] if i+1 < len(nodes) else None
        nodes[i].random = nodes[random] if random is not None else None
    copies = {node:Node(node.val) for node in nodes}
    for node in nodes:
        copies[node].next = copies.get(node.next)
        copies[node].random = copies.get(node.random)
    copied = [copies[node] for node in nodes]
    indices = {node:i for i,node in enumerate(copied)}
    assert all(a is not b for a,b in zip(nodes,copied))
    return [[node.val,indices.get(node.random)] for node in copied]

