def solve(board,words):
    if not board or not board[0]: return []
    root={}
    for word in words:
        node=root
        for ch in word: node=node.setdefault(ch,{})
        node['$']=word
    rows,cols=len(board),len(board[0]); used=set(); found=set()
    def visit(r,c,node):
        if not (0<=r<rows and 0<=c<cols) or (r,c) in used: return
        ch=board[r][c]
        if ch not in node: return
        child=node[ch]
        if '$' in child: found.add(child['$'])
        used.add((r,c))
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)): visit(r+dr,c+dc,child)
        used.remove((r,c))
    for r in range(rows):
        for c in range(cols): visit(r,c,root)
    return sorted(found)

